using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace Spectra;
public sealed class InstanceServer(Store store,GameService game,Action<object> emit)
{
 readonly SemaphoreSlim gate=new(1,1);
 readonly ConcurrentDictionary<string,Process> running=new();
 readonly ConcurrentDictionary<string,ConcurrentQueue<string>> logs=new();
 public string Root(string id){if(id=="vanilla")throw new IOException("Создайте отдельную сборку для сервера");store.Get(id);var root=Store.SafePath(store.Root,"servers/"+id);Directory.CreateDirectory(root);return root;}
 public object State(string id){var root=Root(id);var ready=File.Exists(Path.Combine(root,"spectra-server.json"));return new{running=running.ContainsKey(id),ready,address="127.0.0.1",root,log=logs.TryGetValue(id,out var lines)?string.Join("\n",lines):"",files=Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories).Where(p=>!Reparse(root,p)).Take(3000).Select(p=>new{path=Path.GetRelativePath(root,p).Replace('\\','/'),size=new FileInfo(p).Length,editable=Editable(p)}).ToArray()};}
 static bool Reparse(string root,string path){for(string? p=path;p!=null&&p.Length>=root.Length;p=Path.GetDirectoryName(p))if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)return true;return false;}
 static bool Editable(string path)=>new[]{".json",".toml",".cfg",".conf",".properties",".txt",".yml",".yaml",".xml",".js",".py",".java",".cs",".bat",".sh",".log"}.Contains(Path.GetExtension(path).ToLowerInvariant());
 string FilePath(string id,string relative){var root=Root(id);var path=Store.SafePath(root,relative);if(!File.Exists(path)||Reparse(root,path))throw new IOException("Файл отсутствует или является ссылкой");return path;}
 public async Task<string> Read(string id,string relative){var path=FilePath(id,relative);if(!Editable(path)||new FileInfo(path).Length>1024*1024)throw new IOException("Редактор поддерживает текстовые файлы до 1 МиБ");return await File.ReadAllTextAsync(path);}
 public async Task Write(string id,string relative,string text){if(running.ContainsKey(id))throw new IOException("Остановите сервер перед изменением файлов");var path=FilePath(id,relative);if(!Editable(path)||text.Length>1024*1024)throw new IOException("Неверный текстовый файл");File.Copy(path,path+".spectra-backup",true);await File.WriteAllTextAsync(path,text);}
 void Log(string id,string line){var queue=logs.GetOrAdd(id,_=>new());queue.Enqueue(line);while(queue.Count>1000)queue.TryDequeue(out _);emit(new{type="serverLog",instanceId=id,line});}
 public static string ModSide(string file)
 {
  try{using var zip=ZipFile.OpenRead(file);var entry=zip.GetEntry("fabric.mod.json");if(entry!=null&&entry.Length<1024*1024){using var reader=new StreamReader(entry.Open());var env=JsonNode.Parse(reader.ReadToEnd()).Str("environment");return env switch{"client"=>"client","server"=>"server","*" or ""=>"both",_=>"unknown"};}var quilt=zip.GetEntry("quilt.mod.json");if(quilt!=null&&quilt.Length<1024*1024){using var reader=new StreamReader(quilt.Open());var env=JsonNode.Parse(reader.ReadToEnd())?["minecraft"].Str("environment");return env switch{"client"=>"client","dedicated_server"=>"server","*"=>"both",_=>"unknown"};}}catch(Exception e) when(e is IOException or InvalidDataException or JsonException or InvalidOperationException){}return "unknown";
 }
 public async Task Create(string id,bool acceptEula,bool allowOffline)
 {
  if(!acceptEula)throw new IOException("Для установки сервера примите Minecraft EULA");await gate.WaitAsync();try{
   if(running.ContainsKey(id))throw new IOException("Остановите сервер");var instance=store.Get(id);var root=Root(id);var marker=Path.Combine(root,"spectra-server.json");if(File.Exists(marker))throw new IOException("Сервер уже создан. Его файлы сохранены.");
   var java=await game.ServerJava(instance);java=ConsoleJava(java);var args=new List<string>();
   if(instance.Loader=="vanilla"){var meta=await game.Metadata(instance.Version);var download=meta["downloads"]?["server"]??throw new IOException("Для этой версии нет серверного JAR");await Net.Download(download.Str("url"),Path.Combine(root,"server.jar"),download.Str("sha1"));args.AddRange(["-jar","server.jar","nogui"]);}
   else if(instance.Loader=="fabric"){var installers=await Net.Get("https://meta.fabricmc.net/v2/versions/installer");var version=installers[0].Str("version");await Net.Download($"https://meta.fabricmc.net/v2/versions/loader/{Uri.EscapeDataString(instance.Version)}/{Uri.EscapeDataString(instance.LoaderVersion)}/{Uri.EscapeDataString(version)}/server/jar",Path.Combine(root,"fabric-server.jar"));args.AddRange(["-jar","fabric-server.jar","nogui"]);}
   else if(instance.Loader=="quilt"){var installerVersion=System.Xml.Linq.XDocument.Parse(await Net.Http.GetStringAsync("https://maven.quiltmc.org/repository/release/org/quiltmc/quilt-installer/maven-metadata.xml")).Descendants("release").First().Value;await Net.Download($"https://maven.quiltmc.org/repository/release/org/quiltmc/quilt-installer/{installerVersion}/quilt-installer-{installerVersion}.jar",Path.Combine(root,"installer.jar"));await Installer(ConsoleJava(await game.InstallerJava(instance)),root,["-jar","installer.jar","install","server",instance.Version,instance.LoaderVersion,"--download-server","--install-dir=\""+root+"\""],id);args.AddRange(["-jar","quilt-server-launch.jar","nogui"]);}
   else if(instance.Loader is "forge" or "neoforge"){var name=instance.Loader=="forge"?"forge":"neoforge";var version=instance.Loader=="forge"?instance.Version+"-"+instance.LoaderVersion:instance.LoaderVersion;var host=instance.Loader=="forge"?"https://maven.minecraftforge.net/net/minecraftforge/forge":"https://maven.neoforged.net/releases/net/neoforged/neoforge";await Net.Download($"{host}/{version}/{name}-{version}-installer.jar",Path.Combine(root,"installer.jar"));await Installer(ConsoleJava(await game.InstallerJava(instance)),root,["-jar","installer.jar","--installServer",root],id);var winArgs=Directory.EnumerateFiles(Path.Combine(root,"libraries"),"win_args.txt",SearchOption.AllDirectories).FirstOrDefault();if(winArgs!=null)args.Add("@"+Path.GetRelativePath(root,winArgs));else{var jar=Directory.EnumerateFiles(root,"*.jar").FirstOrDefault(p=>Path.GetFileName(p).StartsWith(name+"-")&&!p.EndsWith("installer.jar"))??throw new IOException("Загрузчик не создал серверный JAR");args.AddRange(["-jar",Path.GetFileName(jar)]);}args.Add("nogui");}
   else throw new IOException("Неизвестный серверный загрузчик");
   var mods=Path.Combine(store.Folder(instance),"mods");var serverMods=Path.Combine(root,"mods");Directory.CreateDirectory(serverMods);var skipped=new List<string>();if(Directory.Exists(mods))foreach(var mod in Directory.EnumerateFiles(mods,"*.jar")){var name=Path.GetFileName(mod);var side=instance.ModSides.GetValueOrDefault(name,ModSide(mod));if(side is "server" or "both")File.Copy(mod,Path.Combine(serverMods,name),true);else if(side=="unknown")skipped.Add(name);}
   await File.WriteAllTextAsync(Path.Combine(root,"eula.txt"),"eula=true\n");var properties=Path.Combine(root,"server.properties");if(!File.Exists(properties))await File.WriteAllTextAsync(properties,"server-ip=127.0.0.1\nserver-port=25565\nonline-mode="+(allowOffline?"false":"true")+"\nmotd=Spectra localhost\n");
   await File.WriteAllTextAsync(marker,JsonSerializer.Serialize(new{version=instance.Version,loader=instance.Loader,loaderVersion=instance.LoaderVersion,args,skipped},Store.Json));foreach(var mod in skipped)Log(id,"Сторона не определена, мод не скопирован: "+mod);Log(id,"Сервер создан. Адрес: localhost:25565");
  }finally{gate.Release();}
 }
 static string ConsoleJava(string java){var console=Path.Combine(Path.GetDirectoryName(java)!,"java.exe");return File.Exists(console)?console:java;}
 async Task Installer(string java,string root,string[] args,string id){using var process=new Process{StartInfo=Info(java,root,args)};process.OutputDataReceived+=(_,e)=>{if(e.Data!=null)Log(id,e.Data);};process.ErrorDataReceived+=(_,e)=>{if(e.Data!=null)Log(id,e.Data);};process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(15));try{await process.WaitForExitAsync(timeout.Token);}catch{process.Kill(true);throw;}if(process.ExitCode!=0)throw new IOException("Установка загрузчика сервера завершилась с ошибкой. Смотрите консоль.");}
 static ProcessStartInfo Info(string java,string root,IEnumerable<string> args){var info=new ProcessStartInfo(java){WorkingDirectory=root,UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true,CreateNoWindow=true};foreach(var arg in args)info.ArgumentList.Add(arg);return info;}
 public async Task Start(string id){await gate.WaitAsync();try{if(running.ContainsKey(id))throw new IOException("Сервер уже запущен");var instance=store.Get(id);var root=Root(id);var manifest=JsonNode.Parse(await File.ReadAllTextAsync(Path.Combine(root,"spectra-server.json")))!;if(manifest.Str("version")!=instance.Version||manifest.Str("loader")!=instance.Loader||manifest.Str("loaderVersion")!=instance.LoaderVersion)throw new IOException("Сборка изменилась. Сервер использует старую версию; сохраните мир перед обновлением.");var java=ConsoleJava(await game.ServerJava(instance));var args=new[]{"-Xms512M","-Xmx"+instance.Settings.MaxRam+"M"}.Concat(manifest["args"]!.AsArray().Select(a=>a!.ToString()));var process=new Process{StartInfo=Info(java,root,args),EnableRaisingEvents=true};process.OutputDataReceived+=(_,e)=>{if(e.Data!=null)Log(id,e.Data);};process.ErrorDataReceived+=(_,e)=>{if(e.Data!=null)Log(id,e.Data);};process.Exited+=(_,_)=>{running.TryRemove(id,out _);Log(id,"Сервер остановлен · "+process.ExitCode);emit(new{type="serverStatus",instanceId=id,running=false});process.Dispose();};running[id]=process;try{process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();emit(new{type="serverStatus",instanceId=id,running=true});}catch{running.TryRemove(id,out _);process.Dispose();throw;}}finally{gate.Release();}}
 public async Task Stop(string id){if(!running.TryGetValue(id,out var process))return;try{await process.StandardInput.WriteLineAsync("stop");await process.StandardInput.FlushAsync();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(20));try{await process.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){process.Kill(true);}}catch(InvalidOperationException){}}
 public async Task Command(string id,string command){if(command.Length>1000||command.Any(char.IsControl))throw new IOException("Неверная команда");if(!running.TryGetValue(id,out var process))throw new IOException("Сервер не запущен");await process.StandardInput.WriteLineAsync(command);await process.StandardInput.FlushAsync();}
}
